def transform(grid):
    g = np.array(grid)
    h, w = g.shape
    bg = background(g)                 # most common colour acts as the stencil
    out = np.zeros((h * h, w * w), dtype=int)
    emit(out, f"Allocate a {h*h}x{w*w} canvas of 0: a {h}x{w} arrangement of {h}x{w} blocks.")
    for y in range(h):
        for x in range(w):
            if g[y, x] == bg:
                out[y*h:(y+1)*h, x*w:(x+1)*w] = g
                emit(out, f"Cell ({y},{x}) holds the dominant colour {bg}: stamp a copy of the input tile into block ({y},{x}).")
    emit(out, "All dominant-colour cells stamped; remaining blocks stay 0.")
    return out
